// src/App.js
import React, { useState, useEffect, useRef } from 'react';
import MapDisplay from './MapDisplay';
import './App.css';

function App() {
  // State for daily customer count.
  const [dailyCustomerCount, setDailyCustomerCount] = useState(0);

  // Customer-related state.
  const [customers, setCustomers] = useState([]);
  const [selectedCustomerIds, setSelectedCustomerIds] = useState([]);
  const [searchTerm, setSearchTerm] = useState("");

  // Truck & product details.
  const [numTrucks, setNumTrucks] = useState(0);
  const [productWeight, setProductWeight] = useState(0);

  // Storage options and selected storage (only one).
  const [storages, setStorages] = useState([]);
const [storageSearchTerm, setStorageSearchTerm] = useState("");
const filteredStorages = storages.filter(
  ({ name, address }) =>
    name.toLowerCase().includes(storageSearchTerm.toLowerCase()) ||
    address.toLowerCase().includes(storageSearchTerm.toLowerCase())
);


  // Optimization result.
  const [optimizationResult, setOptimizationResult] = useState(null);

  // Ref to close suggestions on outside click
  const suggestionRef = useRef(null);

  useEffect(() => {
    // Fetch customers
    fetch("http://127.0.0.1:5000/customers")
      .then(res => res.json())
      .then(data => {
        setCustomers(data.customers.map(c => ({
          id:       c.CustomerID,
          name:     c.CustomerName,
          address:  c.CustomerAddress,
          location: [c.CustomerLat, c.CustomerLong],
        })));
      })
      .catch(console.error);

    // Fetch storages
    fetch("http://127.0.0.1:5000/storages")
      .then(res => res.json())
      .then(data => {
        const list = data.storages.map(s => ({
          id:       s.StorageID,
          name:     s.StorageName,
          address:  s.StorageAddress,
          location: [s.StorageLat, s.StorageLong],
        }));
        setStorages(list);
        if (list.length) setSelectedStorageId(list[0].id);
      })
      .catch(console.error);

    // click outside to close suggestions
    const onClickOutside = e => {
      if (suggestionRef.current && !suggestionRef.current.contains(e.target)) {
        setSearchTerm("");
      }
    };
    document.addEventListener('mousedown', onClickOutside);
    return () => document.removeEventListener('mousedown', onClickOutside);
  }, []);

  // Add or remove a customer from selected stops
  const toggleCustomer = id => {
    setSelectedCustomerIds(ids =>
      ids.includes(id)
        ? ids.filter(x => x !== id)
        : [...ids, id]
    );
  };

  // Remove tag
  const removeCustomer = id =>
    setSelectedCustomerIds(ids => ids.filter(x => x !== id));

  // Filtered suggestions (exclude already selected)
  const suggestions = searchTerm.trim()
    ? customers.filter(c =>
        !selectedCustomerIds.includes(c.id) &&
        c.name.toLowerCase().includes(searchTerm.toLowerCase())
      ).slice(0, 5)
    : [];

  // Submit for optimization: storage as depot index 0
  const handleSubmit = async () => {
    const depot = storages.find(s => s.id === selectedStorageId)?.location;
    if (!depot) return alert("Please select a storage first.");

    const stops = selectedCustomerIds.map(id =>
      customers.find(c => c.id === id).location
    );

    const payload = {
      locations:    [depot, ...stops],
      num_vehicles: numTrucks,
      depot_index:  0,
      daily_customers: dailyCustomerCount,
      total_weight: productWeight,
    };

    try {
      const res = await fetch("http://127.0.0.1:5000/optimize", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      });
      const json = await res.json();
      setOptimizationResult(json);
    } catch (e) {
      console.error(e);
      alert("Failed to optimize routes.");
    }
  };

  // Map data
  const routeData = optimizationResult?.optimized_route?.routes?.[0]?.route || [];
  const defaultCenter = storages.find(s => s.id === selectedStorageId)?.location || [0, 0];

  return (
    <div className="container">
      <header className="header">
        <div className="header-left">
          <h1 className="route-name">Delivery Optimizer</h1>
          <p className="route-desc">Your daily route optimization solution</p>
        </div>
        <div className="header-right">
          <button className="btn new-route">+ New Route</button>
        </div>
      </header>

      <div className="content">
        <aside className="sidebar">
          {/* Storage selector */}
          <div className="storages-section">
            <h3>Start From Storage</h3>
            <div className="storage-list">
              {storages.map(s => (
                <div
                  key={s.id}
                  onClick={() => setSelectedStorageId(s.id)}
                  className={`storage-item ${selectedStorageId === s.id ? 'selected' : ''}`}
                >
                  <strong>{s.name}</strong>
                  <p>{s.address}</p>
                </div>
              ))}
            </div>
          </div>

          {/* Customer live-search & tags */}
          <div className="stops-section" ref={suggestionRef}>
            <h3>Stops</h3>
            {/* Selected tags */}
            <div className="selected-tags">
              {selectedCustomerIds.map(id => {
                const c = customers.find(x => x.id === id);
                return (
                  <span key={id} className="tag">
                    {c.name}
                    <button onClick={() => removeCustomer(id)}>×</button>
                  </span>
                );
              })}
            </div>

            {/* Search input */}
            <input
              type="text"
              className="search-input"
              placeholder="Type to search customers..."
              value={searchTerm}
              onChange={e => setSearchTerm(e.target.value)}
            />

            {/* Suggestion dropdown */}
            {suggestions.length > 0 && (
              <ul className="suggestions-list">
                {suggestions.map(c => (
                  <li key={c.id} onClick={() => { toggleCustomer(c.id); setSearchTerm(""); }}>
                    {c.name} — {c.address}
                  </li>
                ))}
              </ul>
            )}
          </div>
        </aside>

        <main className="main-area">
          <div className="form-section">
            <div className="input-group">
              <label>Daily Customer Count:</label>
              <input
                type="number" min="0"
                value={dailyCustomerCount}
                onChange={e => setDailyCustomerCount(+e.target.value)}
                className="number-input"
              />
            </div>
            <div className="input-group">
              <label>Trucks Needed:</label>
              <input
                type="number" min="0"
                value={numTrucks}
                onChange={e => setNumTrucks(+e.target.value)}
                className="number-input"
              />
            </div>
            <div className="input-group">
              <label>Product Weight (kg):</label>
              <input
                type="number" min="0"
                value={productWeight}
                onChange={e => setProductWeight(+e.target.value)}
                className="number-input"
              />
            </div>
            <button onClick={handleSubmit} className="btn optimize-btn">
              Submit for Optimized Route
            </button>
          </div>

          <div className="map-container">
            <MapDisplay routeData={routeData} defaultCenter={defaultCenter} zoom={13} />
          </div>
        </main>
      </div>

      {optimizationResult && (
        <div className="result-container">
          <h2>Optimization Result</h2>
          <pre className="result-output">
            {JSON.stringify(optimizationResult, null, 2)}
          </pre>
        </div>
      )}
    </div>
  );
}

export default App;
